		return 0, 0, false
	}
	var evt eventMsgPayload
	if json.Unmarshal(line.Payload, &evt) != nil || evt.Type != "token_count" || len(evt.Info) == 0 {
		return 0, 0, false
	}
	var info tokenCountInfo
	if json.Unmarshal(evt.Info, &info) != nil || info.TotalTokenUsage == nil {
		return 0, 0, false
	}
