	program teaRunner

	mu       sync.Mutex
	started  bool
	finished bool
	dropped  int

	msgs     chan tea.Msg  // bounded dispatch queue drained by the pump
	done     chan struct{} // closed when the tea.Program exits
	pumpDone chan struct{} // closed when the pump goroutine exits
}

