	prog := newRecordingProgram()
	sink := newTUISinkWithProgram(prog)
	sink.Start()
	prog.Kill()
	sink.Wait()
	select {
	case <-sink.pumpDone:
	case <-time.After(2 * time.Second):
		t.Fatal("Wait returned before the pump goroutine exited")
	}
}
